<?php
session_start();
if (empty($_SESSION['user_id'])) { header('Location: login.php'); exit; }
$role = strtolower((string)($_SESSION['user_role'] ?? 'student'));
if (!in_array($role, ['student','teacher','admin'], true)) { http_response_code(403); exit('Access denied.'); }
function ah($v): string { return htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8'); }
$userId = (int)$_SESSION['user_id'];
$isStudent = $role === 'student';
$isAdmin = $role === 'admin';
$error = ''; $rows = []; $daily = []; $stats = ['attempts'=>0,'students'=>0,'minutes'=>0,'active_days'=>0];
try {
  $pdo = new PDO('mysql:host=127.0.0.1;port=3306;dbname=kanji_master;charset=utf8mb4','root','root',[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]);
  $base = " FROM practice_attempts p JOIN users u ON u.id=p.user_id JOIN kanji k ON k.id=p.kanji_id ";
  $where = ''; $params = [];
  if ($isStudent) { $where = ' WHERE p.user_id=?'; $params[] = $userId; }
  elseif (!$isAdmin) { $where = ' WHERE EXISTS (SELECT 1 FROM teacher_kanji_assignment_students ts JOIN teacher_kanji_assignments ta ON ta.id=ts.assignment_id WHERE ts.student_id=p.user_id AND ta.teacher_id=?)'; $params[] = $userId; }
  $q = $pdo->prepare('SELECT COUNT(*) attempts, COUNT(DISTINCT p.user_id) students, COALESCE(SUM(p.duration_seconds),0) seconds, COUNT(DISTINCT DATE(p.created_at)) active_days'.$base.$where);
  $q->execute($params); $s = $q->fetch() ?: [];
  $stats['attempts']=(int)($s['attempts']??0); $stats['students']=(int)($s['students']??0); $stats['minutes']=(int)floor(((int)($s['seconds']??0))/60); $stats['active_days']=(int)($s['active_days']??0);
  $q=$pdo->prepare('SELECT p.created_at,p.drawn_stroke_count,p.duration_seconds,k.kanji_character,k.meaning,u.name AS student_name'.$base.$where.' ORDER BY p.created_at DESC,p.id DESC LIMIT 100');
  $q->execute($params); $rows=$q->fetchAll();
  $dailyWhere = $where ? $where.' AND p.created_at >= DATE_SUB(CURDATE(), INTERVAL 13 DAY)' : ' WHERE p.created_at >= DATE_SUB(CURDATE(), INTERVAL 13 DAY)';
  $q=$pdo->prepare('SELECT DATE(p.created_at) day,COUNT(*) attempts'.$base.$dailyWhere.' GROUP BY DATE(p.created_at) ORDER BY day ASC');
  $q->execute($params); foreach($q->fetchAll() as $d) $daily[$d['day']]=(int)$d['attempts'];
} catch(Throwable $e) { error_log('Kanji Master study activity: '.$e->getMessage()); $error='Could not load study activity. Check that MAMP MySQL is running and the practice_attempts table exists. Save a practice attempt first if this is a new installation.'; }
$chart=[]; $max=1; for($i=13;$i>=0;$i--){$day=date('Y-m-d',strtotime('-'.$i.' days'));$v=$daily[$day]??0;$chart[]=['day'=>$day,'label'=>date('M j',strtotime($day)),'value'=>$v];$max=max($max,$v);}
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Study Activity | Kanji Master</title>
<style>*{box-sizing:border-box}body{margin:0;background:#0b1020;color:#f8fafc;font:15px/1.5 Arial,Helvetica,sans-serif}a{color:#c7d2fe;text-decoration:none}a:hover{text-decoration:underline}header{display:flex;justify-content:space-between;align-items:center;gap:14px;flex-wrap:wrap;padding:17px 4%;background:#111827;border-bottom:1px solid #263247}.brand{font-weight:800;color:#fff}.brand span{color:#a5b4fc}nav{display:flex;gap:10px;flex-wrap:wrap}nav a{padding:8px 10px;border:1px solid #334155;border-radius:9px;background:#151d31}main{width:min(1120px,94%);margin:30px auto 60px}.eyebrow{font-size:11px;letter-spacing:1.8px;text-transform:uppercase;color:#a5b4fc}h1{font-size:clamp(27px,4vw,38px);margin:7px 0 4px}.muted,.small{color:#cbd5e1}.muted{margin:4px 0 20px}.stats{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:12px;margin:22px 0}.stat,.panel{background:#151d31;border:1px solid #334155;border-radius:15px;padding:17px}.stat span{display:block;color:#cbd5e1;font-size:13px}.stat strong{display:block;font-size:28px;margin-top:7px}.panel{margin-top:18px}.panel h2{margin:0 0 12px;font-size:19px}.chart{display:grid;grid-template-columns:repeat(14,minmax(0,1fr));gap:8px;align-items:end;height:190px;padding:16px 6px 0}.bar-col{height:100%;display:flex;flex-direction:column;justify-content:flex-end;align-items:center;gap:6px;min-width:0}.bar{width:min(28px,75%);min-height:3px;border-radius:6px 6px 0 0;background:linear-gradient(180deg,#a5b4fc,#6366f1)}.bar-label{font-size:10px;color:#cbd5e1;white-space:nowrap;transform:rotate(-35deg);transform-origin:center top;margin-top:5px}.bar-value{font-size:10px;color:#e2e8f0}.table-wrap{overflow-x:auto}table{width:100%;border-collapse:collapse;min-width:680px}th,td{text-align:left;padding:12px 10px;border-bottom:1px solid #334155;vertical-align:top}th{font-size:11px;text-transform:uppercase;letter-spacing:.5px;color:#cbd5e1}.empty,.notice{padding:15px;border-radius:12px;background:#1f2937;color:#cbd5e1}.notice{background:#7f1d1d44;color:#fecaca}@media(max-width:600px){header{align-items:flex-start}main{margin-top:20px}.stat,.panel{padding:14px}.chart{gap:3px}.bar-label{font-size:8px}}
</style></head><body>
<header><div class="brand">字 <span>Kanji Master</span> · Study Activity</div><nav><?php if($isStudent): ?><a href="dashboard.php">← Dashboard</a><a href="practice.php">Practice</a><a href="progress.php">My progress</a><?php else: ?><a href="teacher_dashboard.php">← Teacher dashboard</a><a href="teacher_submissions.php">Submissions</a><a href="progress.php">Student progress</a><?php endif; ?><a href="logout.php">Log out</a></nav></header>
<main><div class="eyebrow"><?= $isStudent ? 'Your learning habits' : 'Learning analytics' ?></div><h1><?= $isStudent ? 'My study activity' : 'Student study activity' ?></h1><p class="muted"><?= $isStudent ? 'Review your saved kanji-writing practice attempts and study frequency.' : 'See saved kanji-writing practice from students linked to your assignments.' ?></p>
<?php if($error): ?><div class="notice"><?=ah($error)?></div><?php else: ?>
<section class="stats"><div class="stat"><span>Saved practice attempts</span><strong><?=number_format($stats['attempts'])?></strong></div><?php if(!$isStudent): ?><div class="stat"><span>Students with activity</span><strong><?=number_format($stats['students'])?></strong></div><?php endif; ?><div class="stat"><span>Total practice time</span><strong><?=number_format($stats['minutes'])?> min</strong></div><div class="stat"><span>Days with activity</span><strong><?=number_format($stats['active_days'])?></strong></div></section>
<section class="panel"><h2>Daily practice · Last 14 days</h2><p class="small">Number of practice attempts saved each day.</p><div class="chart" role="img" aria-label="Bar chart showing daily saved practice attempts over the last 14 days"><?php foreach($chart as $c): ?><div class="bar-col"><span class="bar-value"><?=$c['value']?:''?></span><div class="bar" style="height:<?=max(2,(int)round($c['value']/$max*125))?>px" title="<?=ah($c['label'])?>: <?=$c['value']?> attempts"></div><span class="bar-label"><?=ah($c['label'])?></span></div><?php endforeach; ?></div></section>
<section class="panel"><h2>Recent practice attempts</h2><?php if(!$rows): ?><div class="empty">No saved practice attempts found yet. Complete a kanji-writing exercise and select “Save practice” to begin tracking activity.</div><?php else: ?><div class="table-wrap"><table><thead><tr><?php if(!$isStudent): ?><th>Student</th><?php endif; ?><th>Kanji</th><th>Meaning</th><th>Strokes drawn</th><th>Duration</th><th>Saved at</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><?php if(!$isStudent): ?><td><?=ah($r['student_name'])?></td><?php endif; ?><td style="font-size:24px;font-weight:800"><?=ah($r['kanji_character'])?></td><td><?=ah($r['meaning'])?></td><td><?=number_format((int)$r['drawn_stroke_count'])?></td><td><?=number_format((int)$r['duration_seconds'])?> sec</td><td><?=ah(date('Y-m-d H:i',strtotime($r['created_at'])))?></td></tr><?php endforeach; ?></tbody></table></div><p class="small" style="margin-top:12px">Showing up to the latest 100 attempts available in your view. Only saved practice is counted.</p><?php endif; ?></section>
<?php endif; ?></main></body></html>
